#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    long long x1, y1, x2, y2;
} Rect;

static inline long long dist_rect(const Rect *a, const Rect *b) {
    long long dx = 0;
    if (a->x2 < b->x1) {
        dx = b->x1 - a->x2;
    } else if (b->x2 < a->x1) {
        dx = a->x1 - b->x2;
    }

    long long dy = 0;
    if (a->y2 < b->y1) {
        dy = b->y1 - a->y2;
    } else if (b->y2 < a->y1) {
        dy = a->y1 - b->y2;
    }

    return dx + dy;
}

int main() {
    long long xi, yi, xf, yf;
    if (scanf("%lld %lld %lld %lld", &xi, &yi, &xf, &yf) != 4) {
        return 0;
    }

