        rects[i].x1 = x1;
        rects[i].y1 = y1;
        rects[i].x2 = x2;
        rects[i].y2 = y2;
    }

    // Nó N + 1: Posição final
    rects[n + 1].x1 = xf;
    rects[n + 1].x2 = xf;
    rects[n + 1].y1 = yf;
    rects[n + 1].y2 = yf;

    long long *dist = (long long *)malloc(total_nodes * sizeof(long long));
    int *visited = (int *)calloc(total_nodes, sizeof(int));

    for (int i = 0; i < total_nodes; i++) {
        dist[i] = LLONG_MAX;
