    for (int i = 0; i < total_nodes; i++) {
        int u = -1;
        long long min_d = LLONG_MAX;

        for (int j = 0; j < total_nodes; j++) {
            if (!visited[j] && dist[j] < min_d) {
                min_d = dist[j];
                u = j;
            }
        }

        if (u == -1 || u == n + 1) {
            break;
        }

        visited[u] = 1;

        for (int v = 0; v < total_nodes; v++) {
            if (!visited[v]) {
                long long weight = dist_rect(&rects[u], &rects[v]);
                if (dist[u] + weight < dist[v]) {
                    dist[v] = dist[u] + weight;
                }
            }
        }
    }

    printf("%lld\n", dist[n + 1]);

    free(rects);
    free(dist);
    free(visited);

    return 0;
